// Title: How to apply a custom cell style to smart‑marker‑generated cells after WorkbookDesigner processing in C# with Aspose.Cells
// Common Searches: C# Aspose.Cells apply custom style to cells generated by smart markers after processing | Set font color, size and borders for smart marker output cells using WorkbookDesigner | How to format non‑empty cells in an Excel workbook after Aspose.Cells smart marker processing | Apply centered alignment and border style to smart marker results with Aspose.Cells .NET | Automate styling of populated cells after WorkbookDesigner.Process in Aspose.Cells
// Tags: custom style after WorkbookDesigner processing | smart marker cell formatting Aspose.Cells | non‑empty cell styling C# Excel | font color and border automation Aspose.Cells | centered alignment for generated Excel data

using Aspose.Cells;
using System;
using System.Collections.Generic;
using System.Data;
using System.Drawing;
using System.IO;

// The example loads an Excel workbook containing smart markers, supplies a DataTable as the data source, processes the markers with WorkbookDesigner, creates a custom Style (dark blue 12‑pt font, centered alignment, thin bottom border), iterates through all worksheets and applies this style to every non‑empty cell populated by the smart markers, and saves the styled workbook.
class Program
{
    static void Main()
    {
        try
        {
            const string inputPath = "input.xlsx";
            const string outputPath = "output.xlsx";

            // Verify that the input workbook exists
            if (!File.Exists(inputPath))
            {
                Console.WriteLine($"Error: Input file \"{inputPath}\" not found.");
                return;
            }

            // Load the workbook that contains smart markers
            Workbook workbook = new Workbook(inputPath);

            // Prepare a data source for the smart markers
            DataTable dt = new DataTable("Employees");
            dt.Columns.Add("Name", typeof(string));
            dt.Columns.Add("Age", typeof(int));

            var data = new List<Dictionary<string, object>>
            {
                new Dictionary<string, object> { { "Name", "John" }, { "Age", 30 } },
                new Dictionary<string, object> { { "Name", "Jane" }, { "Age", 25 } }
            };

            foreach (var row in data)
            {
                dt.Rows.Add(row["Name"], row["Age"]);
            }

            // Process the smart markers using WorkbookDesigner
            WorkbookDesigner designer = new WorkbookDesigner(workbook);
            designer.SetDataSource(dt);
            designer.Process();

            // Create a custom style to apply after processing
            Style customStyle = workbook.CreateStyle();
            customStyle.Font.Color = Color.DarkBlue;
            customStyle.Font.Size = 12;
            customStyle.HorizontalAlignment = TextAlignmentType.Center;
            customStyle.VerticalAlignment = TextAlignmentType.Center;
            customStyle.Borders[BorderType.BottomBorder].LineStyle = CellBorderType.Thin;
            customStyle.Borders[BorderType.BottomBorder].Color = Color.Black;

            // Apply the custom style to all non‑empty cells (populated by smart markers)
            foreach (Worksheet sheet in workbook.Worksheets)
            {
                foreach (Cell cell in sheet.Cells)
                {
                    // Determine if a cell contains data
                    if (cell.Value != null && !(cell.Value is string str && string.IsNullOrEmpty(str)))
                    {
                        cell.SetStyle(customStyle);
                    }
                }
            }

            // Ensure the output directory exists
            string outputDir = Path.GetDirectoryName(outputPath);
            if (!string.IsNullOrEmpty(outputDir) && !Directory.Exists(outputDir))
            {
                Directory.CreateDirectory(outputDir);
            }

            // Save the workbook with the applied styles
            workbook.Save(outputPath);
            Console.WriteLine($"Workbook saved successfully to \"{outputPath}\".");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
